#!/usr/bin/env ruby
# Expected outputs were generated by the optimized pre-refactor executable.
require 'open3'
exe, indir = ARGV
input = File.join(indir, 'molecules.smi')
def run(exe, args)
  out, err, status = Open3.capture3(exe, *args)
  abort "#{args.inspect}: #{err}" unless status.success?
  out
end
modes = [[], %w[-j ring], %w[-j iso -j ring], %w[-j env -j iso -j ring],
         %w[-j iso -j ring -j spiro], %w[-j iso -j ring -j double],
         %w[-j iso -j ring -j all], %w[-j ring -Y scaffold]]
modes.each_with_index do |flags, i|
  run(exe, ['-d', 'STORE', '-d', "direct#{i}.bdb", '-n', *flags, input])
  run(exe, ['-d', 'STORE', '-d', "cached#{i}.bdb", '-n', '-Y', 'hash', *flags, input])
  [[], %w[-Y proto]].each_with_index do |format, j|
    args = ['-n', *flags, *format, input]
    direct = run(exe, ['-d', 'LOOKUP', '-d', "direct#{i}.bdb", *args])
    cached = run(exe, ['-d', 'LOOKUP', '-d', "cached#{i}.bdb", *args])
    abort "Cached/direct mismatch for mode #{i}" unless direct == cached
    File.write("mode_#{i}.#{j==0 ? 'txt' : 'proto'}", direct)
  end
end
puts 'shared extraction checks passed'
